"use client";

import { XCircle } from "lucide-react";
import type { Run } from "@/types/runs";

interface FailureDetailsProps {
  run: Run;
}

export function FailureDetails({ run }: FailureDetailsProps) {
  if (run.status !== "FAILED" || !run.failureSignature) return null;

  return (
    <div className="bg-dark-800 rounded-xl border border-dark-700 overflow-hidden">
      <div className="px-6 py-4 border-b border-dark-700 flex items-center gap-3">
        <XCircle className="w-5 h-5 text-red-500" />
        <h2 className="text-lg font-semibold text-white">Failure Details</h2>
      </div>
      <div className="p-6">
        <div className="mb-4">
          <p className="text-sm text-gray-400 mb-1">Error</p>
          <p className="text-red-400 font-mono">{run.failureSignature}</p>
        </div>
        {run.traceback && (
          <div>
            <p className="text-sm text-gray-400 mb-2">Traceback</p>
            <pre className="bg-dark-900 rounded-lg p-4 text-sm text-gray-300 overflow-x-auto">
              {run.traceback}
            </pre>
          </div>
        )}
      </div>
    </div>
  );
}

